document.querySelector('#new-run').click();
for(let guard=0;guard<100 && __tool.state.step!=='end';guard++) {
  const s=__tool.state,item=s.item;
  const click=id=>document.getElementById(id).click();
  const number=n=>{for(const d of String(n))click('key-'+d);click('check');};
  if(s.step==='result')click('next');
  else if(s.step==='guess')number(item.L);
  else if(s.step==='guess2')number(item.secondL);
  else if(s.step==='tool')click('tool-'+__tool.bestTools()[0]);
  else if(['measure','red','blue','difference'].includes(s.step)) {
    if(item.orientation==='curvy' && !s.traced) {
      for(let k=0;k<20;k++)window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight'}));
    }
    for(let k=0;k<8 && s.offset<-.14;k++)click('right');
    for(let k=0;k<8 && !document.getElementById('mark').hidden;k++)click('mark');
    number(s.step==='blue'?item.b:s.step==='difference'?item.a-item.b:item.L);
  } else if(s.step==='place')click('place-'+(item.storyKind==='join'?'end':'zero'));
  else if(s.step==='slip')number(item.answer);
}

